head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > viewChangeAfterEdit]<br/>Body Cell 의 데이터가 변경된 후 발생하는 onafteredit, onviewchange 이벤트의 순서를 설정합니다.",
    "validation" : [
        "DataList 가 바인딩되어 있을 때 의미가 있으며, onviewchange 이벤트는 데이터가 변경된 경우만 발생합니다.",
        "true 설정 시, Body Cell 의 데이터를 변경한 후 포커스 아웃 시 'onbeforeedit -> {데이터 변경} -> oneditend -> onviewchange -> onafteredit' 순서로 이벤트가 발생합니다.",
        "true 설정 시, onafteredit 이벤트의 columnIndex 파라미터가 GridView 표시 기반 Column 인덱스값을 갖습니다.",
        "false 설정 시, Body Cell 의 데이터를 변경한 후 포커스 아웃 시 'onbeforeedit -> {데이터 변경} -> oneditend -> onafteredit -> onviewchange' 순서로 이벤트가 발생합니다.",
        "미설정 시, Body Cell 의 데이터를 변경한 후 포커스 아웃 시 'onbeforeedit -> {데이터 변경} -> oneditend -> onafteredit -> onviewchange' 순서로 이벤트가 발생합니다.",
        "false 설정 시, onafteredit 이벤트의 columnIndex 파라미터가 DataList 모듈 기반 Column 인덱스값을 갖습니다.",
        "onviewchange 이벤트에서 추가 로직(유효성 검증, 다른 데이터 변경 등)을 수행한 뒤 onafteredit 가 실행되도록 할 때 사용합니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출 (gdl_boolean 등)
    $c.gcm.createCommonDatalist();

    // 조건 셀렉트박스 기본값 설정 (정적 select1 은 초기 selectedIndex 미적용)
    //  con_viewChangeAfterEdit 는 gdl_boolean 바인딩 -> setValue 는 코드값('1'미설정/'2'true/'3'false).
    //  viewChangeAfterEdit default 는 false 이므로 기본값을 false(코드 '3') 로 명시한다.
    con_viewChangeAfterEdit.setValue("3");

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  viewChangeAfterEdit 는 렌더 시 결정되는 속성이므로 con 변경 후 "Target 재생성"(btn_createTarget -> comp_init) 으로만 반영한다.
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // con 선택값 (gdl_boolean -> getText: '' 미설정 / 'true' / 'false')
    let vcae = con_viewChangeAfterEdit.getText();
    let appliedLabel = (vcae === '') ? '미설정(기본 false)' : vcae;
    scwin.gVar = { "applied" : appliedLabel };

    // 사용법 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] viewChangeAfterEdit = ' + appliedLabel + ' / DataList 바인딩 편집(text) 그리드. 표시순서(name-city-age-memo) 와 DataList 선언순서(name-age-city-memo) 가 달라 city/age 는 표시 인덱스와 DataList 모듈 인덱스가 다름 (city=표시1/DataList2, age=표시2/DataList1).\n[절차] con 선택 후 Target 재생성 -> 셀을 더블클릭해 편집하고 값을 바꾼 뒤 다른 셀로 포커스아웃.\n[확인] 하단 결과창에 이벤트가 발생 순서대로(위->아래) 출력. true=oneditend 다음 onviewchange 다음 onafteredit / false(미설정 포함)=oneditend 다음 onafteredit 다음 onviewchange. onafteredit 의 colIndex 도 함께 출력(true=표시기반, false=DataList모듈기반 확인). 값을 바꾸지 않고 포커스아웃하면 onviewchange 는 미발생."', '', 'label1');

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 바인딩 DataList
    //  DataList columnInfo 선언순서 = DataList 모듈 Column 인덱스 기준 : name(0), age(1), city(2), memo(3)
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="age" name="age" dataType="text"></w2:column>';
    strDlt += '<w2:column id="city" name="city" dataType="text"></w2:column>';
    strDlt += '<w2:column id="memo" name="memo" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "name": "김철수", "age": "20", "city": "서울", "memo": "메모A" },
        { "name": "이영희", "age": "25", "city": "부산", "memo": "메모B" },
        { "name": "박민준", "age": "30", "city": "대구", "memo": "메모C" },
        { "name": "최서연", "age": "35", "city": "인천", "memo": "메모D" }
    ], false);

    // viewChangeAfterEdit 속성 : '' 미설정이면 속성 미지정(엔진 기본 false), 그 외에는 값 지정
    let vcaeAttr = (vcae === '') ? '' : ('viewChangeAfterEdit="' + vcae + '" ');

    // target 생성
    //  gBody(=header) 표시순서 = GridView 표시 Column 인덱스 기준 : name(0), city(1), age(2), memo(3)
    //   -> DataList 선언순서(name0/age1/city2/memo3) 와 달라, city/age 는 표시 인덱스 != DataList 모듈 인덱스
    //   -> onafteredit columnIndex 가 true(표시기반) / false(DataList모듈기반) 에서 달라지는지 관찰 대상
    //  4개 이벤트(onbeforeedit/oneditend/onviewchange/onafteredit) 를 바인딩하여 발생 순서를 즉시 출력한다.
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" ' + vcaeAttr + 'checkAllType="false" editModeEvent="ondblclick" ev:onbeforeedit="scwin.target1_onbeforeedit" ev:oneditend="scwin.target1_oneditend" ev:onviewchange="scwin.target1_onviewchange" ev:onafteredit="scwin.target1_onafteredit" id="" style="width:720px;height:200px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="150" inputType="text" id="hname" value="name (표시0/DataList0)"></w2:column>';
    strTarget += '<w2:column width="180" inputType="text" id="hcity" value="city (표시1/DataList2)"></w2:column>';
    strTarget += '<w2:column width="180" inputType="text" id="hage" value="age (표시2/DataList1)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hmemo" value="memo (표시3/DataList3)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="150" inputType="text" dataType="text" id="name"></w2:column>';
    strTarget += '<w2:column width="180" inputType="text" dataType="text" id="city"></w2:column>';
    strTarget += '<w2:column width="180" inputType="text" dataType="text" id="age"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" dataType="text" id="memo"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// 편집 시작 시점 : 이전 편집 시퀀스를 정리하고 발생 순서 관찰을 시작한다.
//  (각 핸들러는 발생 즉시 한 줄씩 출력 -> 출력 라인 순서 = 실제 발생 순서, 순서 왜곡 없음)
scwin.target1_onbeforeedit = function (rowIndex, columnIndex, value) {
    let b = wf_body_bottom.getObj("scwin");
    b.btn_clear_onclick();
    b.setReturnValue("===== [viewChangeAfterEdit=" + scwin.gVar.applied + "] 편집 시작 -> 값 변경 후 포커스아웃 시 순서 출력 =====");
    b.setReturnValue("▶ onbeforeedit (row=" + rowIndex + ", colIndex=" + columnIndex + ")");
}



scwin.target1_oneditend = function (rowIndex, columnIndex, value) {
    wf_body_bottom.getObj("scwin").setReturnValue("▶ oneditend (row=" + rowIndex + ", colIndex=" + columnIndex + ", value=" + value + ")");
}



// onviewchange 는 info 객체를 전달받음 (표준 DOM 이벤트 아님). 데이터가 변경된 경우에만 발생.
scwin.target1_onviewchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("▶ onviewchange (colIndex=" + info.colIndex + ", colId=" + info.colId + ", oldValue=" + info.oldValue + ", newValue=" + info.newValue + ")");
}



// onafteredit 의 columnIndex 파라미터 값을 출력 -> viewChangeAfterEdit true/false 에 따른 인덱스 기준 차이 관찰
scwin.target1_onafteredit = function (rowIndex, columnIndex, value) {
    let colId = '';
    try { colId = scwin.target1.getColumnID(columnIndex); } catch (ex) { colId = ''; }
    wf_body_bottom.getObj("scwin").setReturnValue("▶ onafteredit (row=" + rowIndex + ", colIndex=" + columnIndex + ", colId=" + colId + ", value=" + value + ")");
}
